/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` bigint unsigned DEFAULT NULL,
  `action` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entity_id` bigint unsigned DEFAULT NULL,
  `details` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `actor_id` (`actor_id`),
  CONSTRAINT `audit_logs_ibfk_1` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `harvest_inspections` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `location_id` int DEFAULT NULL,
  `batch_lot_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'รหัส Lot ประจำรอบการเก็บเกี่ยว',
  `harvest_process` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ขั้นตอนการเก็บเกี่ยวและการทำก่อนสั่งซื้อ',
  `harvest_schedule` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รอบเวลาตัดสด เช่น 05:00 - 06:30 น.',
  `lab_test_result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'สารตกค้าง 0.00 ppm (ผ่านการตรวจ Rapid Test)',
  `lab_inspector` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี',
  `brix_sweetness` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ค่าความหวานธรรมชาติ',
  `qc_status` enum('passed','pending','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'passed',
  `inspection_date` date NOT NULL,
  `inspection_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_hi_prod` (`product_id`),
  KEY `idx_hi_lot` (`batch_lot_code`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `harvest_inspections` VALUES (13,37,11,'PLK-PT-หนอ-37','1. ตรวจวัดระดับความแก่จัดของผลกล้วย 80-85% บนต้น\n2. ตัดสดรอบเช้าตรู่ 05:30 น. ป้องกันความร้อนสะสม\n3. ล้างทำความสะอาดด้วยระบบน้ำไหลวนลดคราบยาง\n4. ตัดแต่งหวี คัดเกรดพรีเมียม สวมตาข่ายโฟมกันกระแทกส่งตรงจากแปลง','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','สารตกค้าง 0.00 ppm (ตรวจวิเคราะห์ Rapid Test โดย สสจ.ปทุมธานี)','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','18.5 Brix เมื่อสุกธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(14,38,11,'PLK-PT-หนอ-38','1. คัดกล้วยหอมทองแก่ระดับ 75% จากแปลงปลูกของกลุ่ม\n2. สไลซ์บางสม่ำเสมอ ทอดในกระทะควบคุมอุณหภูมิ\n3. สลัดน้ำมันด้วยเครื่องเหวี่ยงสุญญากาศ บรรจุถุงฟอยล์กันความชื้น','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐาน อย. และ มผช. เลขที่ 13-2-04561-6-0001','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสหวานธรรมชาติจากผลกล้วย','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(15,39,12,'PLK-PT-คลอ-39','1. ตัดยอดใบเตยช่วงเวลา 05:00 น. ก่อนโดนแดดแรง\n2. ล้างทำความสะอาดด้วยระบบน้ำโอโซนบริสุทธิ์ 3 ขั้นตอน\n3. ผึ่งสะเด็ดน้ำ คัดขนาดใบ มัดกำด้วยตอกธรรมชาติ\n4. บรรจุถุงระบายอากาศเพื่อคงความสดและกลิ่นหอม','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ตรวจแล็บสารเคมีตกค้าง 0.00 ppm ปลอดภัย 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','กลิ่นหอมระเหยธรรมชาติมาตรฐาน GAP','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(16,40,12,'PLK-PT-คลอ-40','1. คัดเฉพาะใบเตยหอมแก่ปานกลาง ล้างสะอาด\n2. หั่นชิ้นสม่ำเสมอ อบแห้งด้วยความร้อนต่ำเพื่อรักษาสารสำคัญ\n3. บรรจุซองชาเยื่อข้าวโพด Food Grade เป็นมิตรต่อสิ่งแวดล้อม','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐาน มผช. เลขที่ 140/2558','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','ชาสมุนไพร 0 แคลอรี','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(17,41,13,'PLK-PT-ลาด-41','1. เก็บเกี่ยวสมุนไพรสด (พริก ข่า ตะไคร้ หอม กระเทียม) จากแปลงสมาชิก\n2. ล้างทำความสะอาด ขูดคัดแยกสิ่งปนเปื้อน\n3. โขลกและบดด้วยเครื่องบดหินความเร็วต่ำรักษาความหอมของน้ำมันหอมระเหย\n4. บรรจุสุญญากาศและพาสเจอไรซ์เพื่อความปลอดภัย','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ผ่านการตรวจเชื้อจุลินทรีย์และสารกันเสีย 0% ตามเกณฑ์ อย.','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','สูตรสมุนไพรแท้ไม่เติมน้ำตาล','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(18,49,13,'PLK-PT-ลาด-49','1. คัดพริกสดขี้นกและสมุนไพรสวนลุ่มน้ำเจ้าพระยา\n2. ล้างน้ำโอโซน บดละเอียดเนื้อเนียน\n3. บรรจุในห้องปลอดเชื้อมาตรฐาน อย.','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐาน อย. เลขที่ 13-2-02159-2-0004','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสเผ็ดหอมกลมกล่อม','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(19,42,14,'PLK-PT-ลำล-42','1. ตรวจสอบอายุใบสมบูรณ์ 45 วัน\n2. ตัดสดรอบเช้า 05:30 น. ตัดทีละใบเพื่อคงความสด\n3. ล้างน้ำเย็นระบบโอโซนเพื่อชะล้างฝุ่นละออง\n4. บรรจุถุงเจาะรูพิเศษควบคุมความชื้น เก็บในตู้เย็นได้นาน 10-14 วัน','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','สารเคมีตกค้าง 0.00 ppm ปลอดภัยสำหรับทำน้ำปั่นและสลัด','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสหวานมันตามธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(20,50,14,'PLK-PT-ลำล-50','1. ตัดสดเช้ามืดก่อนแดดส่อง\n2. ล้างระบบน้ำหมุนเวียนโอโซนลดอุณหภูมิใบ\n3. บรรจุถุงควบคุมบรรยากาศคงความกรอบได้นาน','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ไนเตรทต่ำกว่าเกณฑ์มาตรฐานสากล 0.00 ppm','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','กรอบหวานธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(21,43,15,'PLK-PT-สาม-43','1. วัดค่าความสุกด้วยสเปกตรัมแสงและระดับน้ำตาล Brix > 9.5\n2. ปลิดผลด้วยมือกรรไกรสแตนเลสปลอดเชื้อ\n3. เช็ดทำความสะอาดด้วยผ้าไมโครไฟเบอร์ปลอดฝุ่น\n4. บรรจุกล่องใสระบายอากาศกันกระแทก','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ตรวจแล็บสารตกค้าง 0.00 ppm ปลอดภัยมาตรฐาน Organic Thailand','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','9.5 - 11.0 Brix หวานชุ่มฉ่ำ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(22,51,15,'PLK-PT-สาม-51','1. ตรวจวัดค่าความหวาน Brix 14-16 Brix\n2. ตัดขั้วผลรูปตัว T ช่วงเช้ามืด\n3. บรรจุกล่องโฟมพรีเมียมพร้อมจัดส่ง','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐานเกษตรอินทรีย์ Organic Thailand','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','14.0 - 16.0 Brix','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(23,44,16,'PLK-PT-หนอ-44','1. เกี่ยวในระยะพลับพลึงที่รวงข้าวสุกเต็มที่ 85%\n2. ลดความชื้นด้วยลมร้อนอุณหภูมิต่ำกว่า 42°C ให้ความชื้นเหลือไม่เกิน 14%\n3. สีสดด้วยลูกยางกะเทาะเปลือก ไม่ขัดขาวจนสูญเสียวิตามิน\n4. บรรจุถุงสุญญากาศ Food Grade พร้อมซองดูดออกซิเจน คงความหอมได้นาน 1 ปี','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ตรวจไม่พบสารเคมีและสารรมยาฆ่ามอด 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','ข้าวพันธุ์แท้ GI ข้าวหอมปทุมธานี 1','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(24,52,16,'PLK-PT-หนอ-52','1. คัดเมล็ดข้าวกล้องหอมปทุมสมบูรณ์\n2. นำไปแช่น้ำบ่มเพาะงอกในอุณหภูมิควบคุมเพื่อสร้างสารกาบาสูงสุด\n3. อบแห้งและบรรจุสุญญากาศ','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','สาร GABA สูงกว่าข้าวกล้องทั่วไป 15 เท่า ปลอดสารเคมี','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','ข้าวสุขภาพรสหอมมัน','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(25,45,17,'PLK-PT-สาม-45','1. เก็บดอกบัวตูมช่วงเช้ามืด 05:00 น. ก่อนดอกบาน\n2. ปลิดเกสรสีทองด้วยมือทีละดอกอย่างทะนุถนอม\n3. อบแห้งด้วยพาราโบล่าโดมพลังงานแสงอาทิตย์\n4. บรรจุกล่องปิดผนึกสุญญากาศรักษาความหอม','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ปลอดสารเคมี ยาฆ่าแมลง และเชื้อรา 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','ชาสมุนไพรธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(26,53,17,'PLK-PT-สาม-53','1. เก็บฝักบัวแก่อ่อนกำลังดีช่วงเช้า\n2. แกะเมล็ดและลอกเยื่อบางด้วยมือ\n3. แช่น้ำเย็นรักษาความสด บรรจุถุงสุญญากาศ','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ปลอดภัย ปราศจากสารฟอกขาว 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสหวานมันตามธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(27,46,18,'PLK-PT-ลำล-46','1. ปลูกด้วยแหนแดงและปุ๋ยหมักชีวภาพอินทรีย์\n2. เกี่ยวเมื่อสุกเต็มที่ นำมาตากแดดธรรมชาติเพื่อไล่ความชื้น\n3. กะเทาะเปลือกด้วยเครื่องสีข้าวอินทรีย์ควบคุมพิเศษ\n4. บรรจุถุงสุญญากาศเพื่อรักษาคุณค่าสารอาหารครบถ้วน','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ตรวจแล็บสารเคมีตกค้าง 0.00 ppm และสารโลหะหนักปลอดภัย 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','คุณค่าโภชนาการอินทรีย์ 100%','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(28,54,18,'PLK-PT-ลำล-54','1. ใช้ปลายข้าวอินทรีย์จากการสีข้าวกลุ่ม\n2. อบสุกด้วยระบบไอน้ำแรงดันและบดเกล็ด\n3. บรรจุซองฟอยล์กันความชื้น','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ไม่ใส่สารกันเสียและผงชูรส 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสธรรมชาติจากข้าวอินทรีย์','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(29,47,19,'PLK-PT-ลาด-47','1. ตัดกล้วยน้ำว้าจากสวนร่องระแหง บ่มสุกธรรมชาติ\n2. ปอกเปลือกและสไลซ์บางด้วยมีดทองเหลือง\n3. ทอดด้วยน้ำมันรำข้าวความร้อนปานกลางและอบไล่น้ำมันด้วยลมร้อน\n4. บรรจุถุงซิปปิดผนึกสนิท','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐาน อย. และ มผช. ปลอดสารกันเสีย','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','ความหวานธรรมชาติจากกล้วยน้ำว้า','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(30,55,19,'PLK-PT-ลาด-55','1. คัดมะนาวแป้นผิวเรียบน้ำดีจากสวน\n2. ล้างยางมะนาวและขูดผิวลดความขม\n3. แช่อิ่มในน้ำผึ้งชันโรงธรรมชาติ 7 วัน บรรจุกระปุกสูญญากาศ','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐานผลิตภัณฑ์ชุมชน มผช. สะอาดปลอดภัย','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสเปรี้ยวอมหวานชุ่มคอ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(31,48,20,'PLK-PT-ลำล-48','1. ควบคุมความชื้นโรงเรือน 85-90% และอุณหภูมิ 28°C\n2. ดึงเก็บเห็ดช่วงเช้ามืด 04:30 น. ในระยะดอกกำลังโตเต็มที่\n3. ตัดแต่งโคนเห็ดและเป่าเศษขี้เลื่อยออกอย่างนุ่มนวล\n4. บรรจุถุงระบายอากาศพร้อมส่งมอบความสดในวันเดียว','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','ตรวจแล็บไร้สารฟอร์มาลินและโลหะหนัก 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสชาติหวานกรอบธรรมชาติ','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18'),(32,56,20,'PLK-PT-ลำล-56','1. คัดเห็ดนางฟ้าสดดอกสมบูรณ์ ฉีกเป็นเส้นพอดีคำ\n2. อบด้วยลมร้อนสุญญากาศไล่ความชื้น\n3. คลุกเคล้าผงปรุงรสต้มยำจากสมุนไพรแท้ บรรจุซองฟอยล์ซิปล็อค','ตัดสดรอบเช้ามืด 05:00 - 06:30 น.','มาตรฐาน อย. และ มผช. ปลอดภัย 100%','ศูนย์ตรวจสอบคุณภาพเกษตรปลอดภัยและแล็บชุมชนปทุมธานี','รสแซ่บต้มยำสมุนไพร','passed','2026-11-05',NULL,'2026-11-05 20:25:18','2026-11-05 20:25:18');
