CREATE TABLE `news` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `author_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `author_id` (`author_id`),
  CONSTRAINT `news_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `news` VALUES (7,'ต้อนรับฤดูกาลเก็บเกี่ยวเมล่อนอินทรีย์รอบพิเศษ ส่งตรงจากแปลงเครือข่ายวิสาหกิจชุมชน','แปลงเพาะปลูกในเครือข่ายวิสาหกิจชุมชนเกษตรอินทรีย์ของเราพร้อมส่งมอบเมล่อนญี่ปุ่นคัดเกรดพิเศษ หวานฉ่ำ ปลูกด้วยดินหมักอินทรีย์ธรรมชาติ ปราศจากสารเคมี 100% ผ่านการรับรองมาตรฐาน GAP สินค้าพร้อมจัดส่งสู่ครัวเรือนแล้ววันนี้',4,'2026-11-05 18:21:28','2026-11-05 18:21:28'),(8,'สัมมนาเชิงปฏิบัติการ: การฟื้นฟูความอุดมสมบูรณ์ของดินและการเพาะปลูกวิถีอินทรีย์ยั่งยืน','ขอเชิญพี่น้องสมาชิกและผู้รักสุขภาพร่วมศึกษาดูงานการฟื้นฟูจุลินทรีย์ในดิน และการตรวจวัดคุณภาพน้ำ เพื่อยกระดับผลผลิตสู่มาตรฐานเกษตรปลอดภัยสากล ณ ศูนย์การเรียนรู้วิสาหกิจชุมชนเกษตรอินทรีย์',4,'2026-11-05 18:21:28','2026-11-05 18:21:28'),(9,'ยกระดับมาตรฐานการจัดส่งผลผลิตสดใหม่ เก็บเกี่ยวรอบเช้าตรู่ส่งตรงถึงบ้านในวันเดียว','เพื่อรักษาความสดกรอบและคุณค่าทางอาหารอย่างสูงสุด ผลผลิตทุกชิ้นที่เก็บเกี่ยวในรอบเช้าตรู่ จะถูกคัดแยก บรรจุลงกล่องมาตรฐาน และส่งตรงถึงมือสมาชิกอย่างรวดเร็ว เพื่อให้ทุกครอบครัวได้รับประทานผลผลิตที่สดใหม่เสมือนเพิ่งเก็บจากแปลง',4,'2026-11-05 18:21:28','2026-11-05 18:21:28');
