/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `product_id` int NOT NULL,
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'กิโลกรัม',
  `subtotal` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_oi_order` (`order_id`),
  KEY `idx_oi_product` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `order_items` VALUES (1,1,37,'กล้วยหอมทองปทุมธานีแท้ GI หวีพรีเมียม (Pathumthani Golden Banana)',85.00,1.00,'หวี (1.8-2.2 กก.)',85.00),(2,2,37,'ผลผลิตเกษตร',85.00,2.00,'หวี',170.00),(3,3,51,'เมลอนมัสค์ญี่ปุ่นโรงเรือนควบคุมอุณหภูมิ (Musk Melon)',290.00,1.00,'ลูก (1.6-1.8 กก.)',290.00);
