INSERT INTO `order_tracking_events` VALUES (1,1,'received','ได้รับคำสั่งซื้อและตรวจสลิปโอนเงินตรงสำเร็จ','ระบบรับชำระ P2P','2026-11-05 20:03:43'),(2,1,'harvested','เกษตรกรตัดสดจากแปลงและแพ็คควบคุมความเย็น','แปลงเพาะปลูก จ.ปทุมธานี','2026-11-05 20:03:43'),(3,1,'shipped','จัดส่งด่วนตรงสู่ครัวเรือนในวันเดียว','ศูนย์กระจายสินค้าชุมชน','2026-11-05 20:03:43'),(4,2,'received','เกษตรกรได้รับคำสั่งซื้อและตรวจหลักฐานการโอนเงินตรงสำเร็จ','ระบบสั่งซื้อตรง ปลูกรัก','2026-11-05 20:07:55'),(5,2,'preparing_harvest','แจ้งแปลงเพาะปลูกเตรียมตัดสดรอบเช้าตามขั้นตอนการเก็บเกี่ยว','หมู่ 1 ต.นพรัตน์ อ.หนองเสือ จ.ปทุมธานี 12170 (ริมคลองระบายน้ำที่ 10 ฝั่งตะวันออก)','2026-11-05 20:07:55'),(6,3,'received','เกษตรกรได้รับคำสั่งซื้อและตรวจหลักฐานการโอนเงินตรงสำเร็จ','ระบบสั่งซื้อตรง ปลูกรัก','2026-11-06 00:15:00'),(7,3,'preparing_harvest','แจ้งแปลงเพาะปลูกเตรียมตัดสดรอบเช้าตามขั้นตอนการเก็บเกี่ยว','หมู่ 3 ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160 (ติดแม่น้ำเจ้าพระยา)','2026-11-06 00:15:00');
