CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `seller_id` int NOT NULL,
  `buyer_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `buyer_phone` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `buyer_address` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `buyer_latitude` decimal(10,7) DEFAULT NULL,
  `buyer_longitude` decimal(10,7) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `payment_method` enum('direct_p2p_transfer','promptpay') COLLATE utf8mb4_unicode_ci DEFAULT 'direct_p2p_transfer',
  `payment_status` enum('pending_verification','paid','verified','failed') COLLATE utf8mb4_unicode_ci DEFAULT 'pending_verification',
  `order_status` enum('received','preparing_harvest','harvested','shipped','completed','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'received',
  `transfer_slip_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'สลิปโอนเงินเข้าบัญชีเกษตรกร',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_code` (`order_code`),
  KEY `idx_order_seller` (`seller_id`),
  KEY `idx_order_code` (`order_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
