INSERT INTO `orders` VALUES (1,'PLK-PT-DEMO-6566',1,'คุณสมศักดิ์ รักสุขภาพ','081-234-5678','99/4 ถ.พหลโยธิน ต.คลองหนึ่ง อ.คลองหลวง จ.ปทุมธานี 12120',NULL,NULL,85.00,'direct_p2p_transfer','verified','completed','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800','โอนเงินตรงสู่บัญชีผู้ขายเรียบร้อย','2026-11-05 20:03:43','2026-11-05 20:03:43'),(2,'PLK-PT-95848',1,'ทดสอบผู้ซื้อ','0812345678','ปทุมธานี',NULL,NULL,170.00,'direct_p2p_transfer','pending_verification','received',NULL,NULL,'2026-11-05 20:07:55','2026-11-05 20:07:55'),(3,'PLK-PT-85983',5,'คุณผู้รักสุขภาพ (ผู้สั่งซื้อออนไลน์)','081-999-8877','จัดส่งตามที่อยู่ปลายทาง',NULL,NULL,290.00,'direct_p2p_transfer','paid','received','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800','คำสั่งซื้อโอนตรงสู่เจ้าของผลผลิตในปทุมธานี','2026-11-06 00:15:00','2026-11-06 00:15:00');
