CREATE TABLE `production_locations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seller_id` int NOT NULL,
  `location_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อแปลงปลูกหรือสถานที่ผลิต',
  `location_type` enum('หน้าแปลง','หน้าสวน','ตลาดวิสาหกิจชุมชน','โรงเรือนปิด','ศูนย์กระจายสินค้า') COLLATE utf8mb4_unicode_ci DEFAULT 'หน้าแปลง',
  `province` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ปทุมธานี',
  `amphoe` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'อำเภอ เช่น หนองเสือ, คลองหลวง, ลาดหลุมแก้ว',
  `tambon` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ตำบล เช่น นพรัตน์, คลองสาม, คูขวาง',
  `origin_address` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ที่อยู่หน้างานละเอียด',
  `latitude` decimal(10,7) DEFAULT NULL COMMENT 'พิกัด GPS ละติจูด',
  `longitude` decimal(10,7) DEFAULT NULL COMMENT 'พิกัด GPS ลองจิจูด',
  `plot_size` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ขนาดพื้นที่เพาะปลูก',
  `water_source` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'แหล่งน้ำที่ใช้ในการเกษตร',
  `farm_photo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รูปถ่ายแปลงปลูกจริง',
  `video_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_loc_seller` (`seller_id`),
  KEY `idx_loc_province` (`province`),
  KEY `idx_loc_type` (`location_type`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
