INSERT INTO `production_locations` VALUES (11,1,'แปลงใหญ่กล้วยหอมทองคลอง 10 นพรัตน์','หน้าแปลง','ปทุมธานี','หนองเสือ','นพรัตน์','หมู่ 1 ต.นพรัตน์ อ.หนองเสือ จ.ปทุมธานี 12170 (ริมคลองระบายน้ำที่ 10 ฝั่งตะวันออก)',14.1725000,100.8652000,'35 ไร่ (สมาชิกเครือข่าย 80 ไร่)','น้ำชลประทานคลองระบายน้ำที่ 10 ผ่านระบบพักบ่ออินทรีย์','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26'),(12,2,'แปลงร่องสวนเตยหอมอินทรีย์คลองสาม','หน้าแปลง','ปทุมธานี','คลองหลวง','คลองสาม','หมู่ 9 ต.คลองสาม อ.คลองหลวง จ.ปทุมธานี 12120',14.0721000,100.6589000,'24 ไร่','น้ำร่องสวนธรรมชาติควบคุมระดับน้ำใต้ผิวดิน','https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80','/videos/farm-field.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:45:42'),(13,3,'ศูนย์แปรรูปเครื่องแกงโบราณคูขวาง','ตลาดวิสาหกิจชุมชน','ปทุมธานี','ลาดหลุมแก้ว','คูขวาง','หมู่ 4 ต.คูขวาง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140',14.0389000,100.4125000,'แปลงสมุนไพรเครือข่าย 15 ไร่ + โรงผลิตมาตรฐาน','ระบบน้ำบาดาลกรอง RO สำหรับโรงงานอาหาร','https://images.unsplash.com/photo-1590682680695-43b964a3ae17?w=800&auto=format&fit=crop&q=80','/videos/farm-greenhouse.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26'),(14,4,'โรงเรือนผักสลัดออร์แกนิคบึงคอไห','หน้าสวน','ปทุมธานี','ลำลูกกา','บึงคอไห','หมู่ 5 ต.บึงคอไห อ.ลำลูกกา จ.ปทุมธานี 12150',13.9845000,100.8210000,'18 ไร่ (12 โรงเรือนมุ้งปิด)','น้ำบาดาลลึก 150 เมตร ผ่านระบบกรองคาร์บอนและแสง UV','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26'),(15,5,'จีฟาร์ม ฟาร์มเกษตรอัจฉริยะริมเจ้าพระยา','หน้าแปลง','ปทุมธานี','สามโคก','กระแชง','หมู่ 3 ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160 (ติดแม่น้ำเจ้าพระยา)',14.0754000,100.5312000,'12 ไร่ (โรงเรือนโซลาร์เซลล์)','น้ำบาดาลผ่านระบบบำบัด RO ควบคุมด้วยเซนเซอร์ IoT','https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800&auto=format&fit=crop&q=80','/videos/farm-field.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26'),(16,6,'ลานตากและโรงสีข้าวชุมชนบึงสมบูรณ์','ตลาดวิสาหกิจชุมชน','ปทุมธานี','หนองเสือ','บึงกาสาม','หมู่ 2 ต.บึงกาสาม อ.หนองเสือ จ.ปทุมธานี 12170',14.1950000,100.8245000,'แปลงนาแปลงใหญ่ 120 ไร่','น้ำชลประทานคลอง 9 และคลอง 10 ควบคุมระดับน้ำตามระยะการเจริญเติบโต','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-nature.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:45:42'),(17,7,'นาบัวหลวงโบราณและศูนย์หัตถกรรมวัดไก่เตี้ย','หน้าสวน','ปทุมธานี','สามโคก','กระแชง','หมู่ 1 ชุมชนวัดไก่เตี้ย ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160',14.0689000,100.5280000,'นาบัว 16 ไร่','น้ำลำคลองเชื่อมต่อแม่น้ำเจ้าพระยา หมุนเวียนธรรมชาติ','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-nature.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26'),(18,8,'ทุ่งนาข้าวอินทรีย์เพราะรักกสิกรรม ลำลูกกา','หน้าแปลง','ปทุมธานี','ลำลูกกา','ลำลูกกา','หมู่ 6 ต.ลำลูกกา อ.ลำลูกกา จ.ปทุมธานี 12150',13.9312000,100.7489000,'50 ไร่','ระบบกักเก็บน้ำฝนธรรมชาติและคลองระบายน้ำชลประทาน','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:45:42'),(19,9,'สวนผลไม้ผสมผสานและโรงแปรรูปชุมชนระแหง','หน้าสวน','ปทุมธานี','ลาดหลุมแก้ว','ระแหง','หมู่ 3 ต.ระแหง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140',14.0512000,100.3890000,'20 ไร่','น้ำร่องสวนธรรมชาติคลองระแหง','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-field.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:45:42'),(20,10,'โรงเรือนเพาะเห็ดอัจฉริยะลำไทร','หน้าแปลง','ปทุมธานี','ลำลูกกา','ลำไทร','หมู่ 13 ต.ลำไทร อ.ลำลูกกา จ.ปทุมธานี 12150',13.9450000,100.8120000,'10 โรงเรือนพ่นหมอกอัจฉริยะ','น้ำบาดาลผ่านการกรองและฆ่าเชื้อด้วยระบบพ่นหมอกความชื้นสัมพัทธ์ 85%','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','/videos/farm-greenhouse.mp4',1,'2026-11-05 20:25:18','2026-11-07 15:23:26');
