CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `farmer_id` bigint unsigned DEFAULT NULL,
  `seller_id` int DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `description` text,
  `harvest_process` text,
  `category` varchar(50) NOT NULL DEFAULT 'other',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `quantity` decimal(10,2) NOT NULL DEFAULT '0.00',
  `unit` varchar(50) NOT NULL DEFAULT 'กิโลกรัม',
  `origin_address` varchar(255) DEFAULT NULL,
  `province` varchar(100) DEFAULT 'นครปฐม',
  `location_type` varchar(50) DEFAULT 'หน้าแปลง',
  `image_url` varchar(500) DEFAULT NULL,
  `video_url` varchar(500) DEFAULT NULL,
  `cert_image_url` varchar(500) DEFAULT NULL,
  `farm_image_url` varchar(500) DEFAULT NULL,
  `cert_number` varchar(100) DEFAULT NULL,
  `bank_name` varchar(100) DEFAULT NULL,
  `bank_account_name` varchar(200) DEFAULT NULL,
  `bank_account_number` varchar(50) DEFAULT NULL,
  `promptpay_number` varchar(50) DEFAULT NULL,
  `seller_phone` varchar(50) DEFAULT NULL,
  `status` enum('available','sold_out','inactive') NOT NULL DEFAULT 'available',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_products_farmer` (`farmer_id`),
  KEY `idx_products_status` (`status`),
  KEY `idx_prod_seller` (`seller_id`),
  CONSTRAINT `fk_products_farmer` FOREIGN KEY (`farmer_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
