INSERT INTO `products` VALUES (37,10,1,'กล้วยหอมทองปทุมธานีแท้ GI หวีพรีเมียม (Pathumthani Golden Banana)','กล้วยหอมทองแท้ GI ปทุมธานี ผลใหญ่ยาว เปลือกบาง ผิวนวล เนื้อเหนียวนุ่ม หวานหอมตามธรรมชาติ ตัดสดรอบเช้า','1. ตรวจวัดระดับความแก่จัดของผลกล้วย 80-85% บนต้น\n2. ตัดสดรอบเช้าตรู่ 05:30 น. ป้องกันความร้อนสะสม\n3. ล้างทำความสะอาดด้วยระบบน้ำไหลวนลดคราบยาง\n4. ตัดแต่งหวี คัดเกรดพรีเมียม สวมตาข่ายโฟมกันกระแทกส่งตรงจากแปลง','fruit',85.00,60.00,'หวี (1.8-2.2 กก.)','หมู่ 1 ต.นพรัตน์ อ.หนองเสือ จ.ปทุมธานี 12170 (ริมคลองระบายน้ำที่ 10 ฝั่งตะวันออก)','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','สช 64100142 (GI) / กษ 03-9001-3829-TH','ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร (ธ.ก.ส.)','นายนุกุล นามปราศัย','020-1-98421-4','0818179418','081-817-9418','available','2026-11-05 20:03:43','2026-11-07 15:23:26'),(38,10,1,'กล้วยหอมทองทอดกรอบ \'หอมนอกกรอบ\' รสธรรมชาติ (Crispy Banana Chips)','แปรรูปจากกล้วยหอมทองปทุมธานีแท้ ทอดด้วยน้ำมันรำข้าว สลัดน้ำมันกรอบอร่อย ไม่อมน้ำมัน ไร้สารกันเสีย','1. คัดกล้วยหอมทองแก่ระดับ 75% จากแปลงปลูกของกลุ่ม\n2. สไลซ์บางสม่ำเสมอ ทอดในกระทะควบคุมอุณหภูมิ\n3. สลัดน้ำมันด้วยเครื่องเหวี่ยงสุญญากาศ บรรจุถุงฟอยล์กันความชื้น','processed',45.00,120.00,'ถุงซิปล็อค (120 กรัม)','หมู่ 1 ต.นพรัตน์ อ.หนองเสือ จ.ปทุมธานี 12170 (ริมคลองระบายน้ำที่ 10 ฝั่งตะวันออก)','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1528750997573-59b89d56f4f7?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','สช 64100142 (GI) / กษ 03-9001-3829-TH','ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร (ธ.ก.ส.)','นายนุกุล นามปราศัย','020-1-98421-4','0818179418','081-817-9418','available','2026-11-05 20:03:43','2026-11-07 15:23:26'),(39,11,2,'ใบเตยหอมสดคัดเกรดพรีเมียม (Fresh Pandan Leaves)','ใบเตยหอมสดตัดใหม่เช้าตรู่จากแปลงร่องสวนคลองสาม ใบใหญ่ เขียวสด กลิ่นหอมฟุ้ง เหมาะสำหรับทำขนมและเครื่องดื่ม','1. ตัดยอดใบเตยช่วงเวลา 05:00 น. ก่อนโดนแดดแรง\n2. ล้างทำความสะอาดด้วยระบบน้ำโอโซนบริสุทธิ์ 3 ขั้นตอน\n3. ผึ่งสะเด็ดน้ำ คัดขนาดใบ มัดกำด้วยตอกธรรมชาติ\n4. บรรจุถุงระบายอากาศเพื่อคงความสดและกลิ่นหอม','vegetable',40.00,150.00,'กิโลกรัม','หมู่ 9 ต.คลองสาม อ.คลองหลวง จ.ปทุมธานี 12120','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1622206151226-18ca2c9ab4a1?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80','GAP-TH-13-02-49102','ธนาคารกสิกรไทย (KBANK)','นางสมปอง คำสวัสดิ์','412-2-58910-3','0865549123','086-554-9123','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(40,11,2,'ชาใบเตยหอมอินทรีย์อบแห้ง (Organic Pandan Tea)','ชาใบเตยหอม 100% กลิ่นหอมชื่นใจ บำรุงหัวใจ ลดระดับน้ำตาลในเลือด ไม่ผสมน้ำตาล ไม่แต่งกลิ่นสังเคราะห์','1. คัดเฉพาะใบเตยหอมแก่ปานกลาง ล้างสะอาด\n2. หั่นชิ้นสม่ำเสมอ อบแห้งด้วยความร้อนต่ำเพื่อรักษาสารสำคัญ\n3. บรรจุซองชาเยื่อข้าวโพด Food Grade เป็นมิตรต่อสิ่งแวดล้อม','processed',89.00,80.00,'กล่อง (20 ซองชา)','หมู่ 9 ต.คลองสาม อ.คลองหลวง จ.ปทุมธานี 12120','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80','GAP-TH-13-02-49102','ธนาคารกสิกรไทย (KBANK)','นางสมปอง คำสวัสดิ์','412-2-58910-3','0865549123','086-554-9123','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(41,12,3,'น้ำพริกแกงเผ็ดโบราณสูตรพ่อกำนัน (Traditional Red Curry Paste)','พริกแกงเผ็ดสูตรมอญโบราณ หอมกลิ่นผิวมะกรูดและตะไคร้สด ไม่ใส่ผงชูรส ไม่เจือสี ไม่ใส่วัตถุกันเสีย ผัดแกงหอมแตกมัน','1. เก็บเกี่ยวสมุนไพรสด (พริก ข่า ตะไคร้ หอม กระเทียม) จากแปลงสมาชิก\n2. ล้างทำความสะอาด ขูดคัดแยกสิ่งปนเปื้อน\n3. โขลกและบดด้วยเครื่องบดหินความเร็วต่ำรักษาความหอมของน้ำมันหอมระเหย\n4. บรรจุสุญญากาศและพาสเจอไรซ์เพื่อความปลอดภัย','processed',65.00,90.00,'กระปุก (500 กรัม)','หมู่ 4 ต.คูขวาง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140','ปทุมธานี','ตลาดวิสาหกิจชุมชน','https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1590682680695-43b964a3ae17?w=800&auto=format&fit=crop&q=80','อย. 13-2-02159-2-0003 / มผช. 28/2555','ธนาคารกรุงไทย (KTB)','นายสมควร ชื่นอารมณ์','132-0-45891-2','0819124589','081-912-4589','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(42,13,4,'เคลไดโนเสาร์ออร์แกนิกตัดสด (Organic Lacinato Dino Kale)','ราชินีผักใบเขียว (Superfood) ใบหยักหนาสีเขียวเข้ม รสหวานมัน ไม่ขม วิตามินซีและแคลเซียมสูง ปลูกในโรงเรือนปิด','1. ตรวจสอบอายุใบสมบูรณ์ 45 วัน\n2. ตัดสดรอบเช้า 05:30 น. ตัดทีละใบเพื่อคงความสด\n3. ล้างน้ำเย็นระบบโอโซนเพื่อชะล้างฝุ่นละออง\n4. บรรจุถุงเจาะรูพิเศษควบคุมความชื้น เก็บในตู้เย็นได้นาน 10-14 วัน','vegetable',95.00,70.00,'ถุง (250 กรัม)','หมู่ 5 ต.บึงคอไห อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1524179091875-bf99a9a6fa57?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','กษ 03-9001-50821-TH','ธนาคารไทยพาณิชย์ (SCB)','นายธนกฤต ศรีบุญเรือง','388-2-41902-8','0897723419','089-772-3419','available','2026-11-05 20:03:43','2026-11-07 15:23:26'),(43,14,5,'มะเขือเทศเชอร์รี่สีทองโซลาร์ฟาร์ม (Golden Sweet Cherry Tomato)','ลูกแน่นกรอบ สีเหลืองทองอร่าม เปลือกบาง รสหวานอมเปรี้ยวกลมกล่อม ไลโคปีนและเบต้าแคโรทีนสูง สุกคาต้น 95%','1. วัดค่าความสุกด้วยสเปกตรัมแสงและระดับน้ำตาล Brix > 9.5\n2. ปลิดผลด้วยมือกรรไกรสแตนเลสปลอดเชื้อ\n3. เช็ดทำความสะอาดด้วยผ้าไมโครไฟเบอร์ปลอดฝุ่น\n4. บรรจุกล่องใสระบายอากาศกันกระแทก','vegetable',85.00,65.00,'กล่อง (350 กรัม)','หมู่ 3 ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160 (ติดแม่น้ำเจ้าพระยา)','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800&auto=format&fit=crop&q=80','ORG-TH-13-07-39120','ธนาคารกสิกรไทย (KBANK)','นางสาวกนกพร ลิ้มประเสริฐ','045-8-91230-5','0846398120','084-639-8120','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(44,15,6,'ข้าวหอมปทุมธานี 1 แท้ GI คัดพิเศษ (Pathumthani Fragrant Rice 1)','ข้าวหอมปทุมธานีแท้ 100% เมล็ดเรียวยาว ขาวนวล เมื่อหุงสุกจะนุ่มเหนียวและมีกลิ่นหอมละมุนคล้ายข้าวหอมมะลิ บรรจุถุงสุญญากาศ','1. เกี่ยวในระยะพลับพลึงที่รวงข้าวสุกเต็มที่ 85%\n2. ลดความชื้นด้วยลมร้อนอุณหภูมิต่ำกว่า 42°C ให้ความชื้นเหลือไม่เกิน 14%\n3. สีสดด้วยลูกยางกะเทาะเปลือก ไม่ขัดขาวจนสูญเสียวิตามิน\n4. บรรจุถุงสุญญากาศ Food Grade พร้อมซองดูดออกซิเจน คงความหอมได้นาน 1 ปี','grain',180.00,100.00,'ถุงสุญญากาศ (5 กก.)','หมู่ 2 ต.บึงกาสาม อ.หนองเสือ จ.ปทุมธานี 12170','ปทุมธานี','ตลาดวิสาหกิจชุมชน','https://images.unsplash.com/photo-1586201375761-83865001e31c?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','สช 61100098 (GI) / กษ 03-4401-2891','ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร (ธ.ก.ส.)','นายประสิทธิ์ บุญมี','020-2-34981-0','0817028934','081-702-8934','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(45,16,7,'ชาเกสรดอกบัวหลวงอบแห้งอินทรีย์ (Organic Sacred Lotus Stamen Tea)','เกสรบัวหลวงแท้จากนาบัวโบราณสามโคก สรรพคุณบำรุงหัวใจ บำรุงสายตา หลับสบาย กลิ่นหอมละมุน ชงดื่มได้ทุกวัน','1. เก็บดอกบัวตูมช่วงเช้ามืด 05:00 น. ก่อนดอกบาน\n2. ปลิดเกสรสีทองด้วยมือทีละดอกอย่างทะนุถนอม\n3. อบแห้งด้วยพาราโบล่าโดมพลังงานแสงอาทิตย์\n4. บรรจุกล่องปิดผนึกสุญญากาศรักษาความหอม','processed',120.00,50.00,'กล่อง (50 กรัม)','หมู่ 1 ชุมชนวัดไก่เตี้ย ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','มผช. 589/2558 / OTOP-PT-5STAR-012','ธนาคารกรุงไทย (KTB)','นางประทีป อ่อนชื่น','115-1-89302-4','0899832145','089-983-2145','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(46,17,8,'ข้าวไรซ์เบอร์รี่อินทรีย์แท้ 100% ทุ่งลำลูกกา (Organic Riceberry)','ข้าวไรซ์เบอร์รี่แท้ เมล็ดสีม่วงเข้มเป็นมันวาว แอนโทไซยานินและสารต้านอนุมูลอิสระสูง หุงนุ่มหนึบ อร่อยเคี้ยวเพลิน','1. ปลูกด้วยแหนแดงและปุ๋ยหมักชีวภาพอินทรีย์\n2. เกี่ยวเมื่อสุกเต็มที่ นำมาตากแดดธรรมชาติเพื่อไล่ความชื้น\n3. กะเทาะเปลือกด้วยเครื่องสีข้าวอินทรีย์ควบคุมพิเศษ\n4. บรรจุถุงสุญญากาศเพื่อรักษาคุณค่าสารอาหารครบถ้วน','grain',110.00,90.00,'ถุงสุญญากาศ (1 กก.)','หมู่ 6 ต.ลำลูกกา อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1586201375761-83865001e31c?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','ORG-TH-13-04-98412','ธนาคารออมสิน (GSB)','นายณัฐพล ใจซื่อ','020-3-48190-2','0873459120','087-345-9120','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(47,18,9,'กล้วยน้ำว้าทองแผ่นอบกรอบเบรกแตก (Crispy Namwa Banana)','กล้วยน้ำว้าสุกกำลังดีทอดกรอบไล่น้ำมัน หอมหวานกลมกล่อมตามธรรมชาติ ไม่เติมน้ำตาล ไม่แต่งกลิ่น ไร้ไขมันทรานส์','1. ตัดกล้วยน้ำว้าจากสวนร่องระแหง บ่มสุกธรรมชาติ\n2. ปอกเปลือกและสไลซ์บางด้วยมีดทองเหลือง\n3. ทอดด้วยน้ำมันรำข้าวความร้อนปานกลางและอบไล่น้ำมันด้วยลมร้อน\n4. บรรจุถุงซิปปิดผนึกสนิท','processed',35.00,140.00,'ถุง (100 กรัม)','หมู่ 3 ต.ระแหง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1528750997573-59b89d56f4f7?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','อย. 13-2-03460-6-0002 / มผช. 52/2554','ธนาคารกสิกรไทย (KBANK)','นางสมใจ สุขสวัสดิ์','248-2-39014-7','0834921876','083-492-1876','available','2026-11-05 20:03:43','2026-11-07 15:23:26'),(48,19,10,'เห็ดนางฟ้าภูฐานสดดอกหนานุ่ม (Fresh Bhutan Oyster Mushroom)','เห็ดนางฟ้าภูฐานสดใหม่ เก็บเช้ามืด 04:30 น. ดอกหนานุ่ม ก้านอวบกรอบ หวานธรรมชาติ ปลอดสารฟอร์มาลิน 100%','1. ควบคุมความชื้นโรงเรือน 85-90% และอุณหภูมิ 28°C\n2. ดึงเก็บเห็ดช่วงเช้ามืด 04:30 น. ในระยะดอกกำลังโตเต็มที่\n3. ตัดแต่งโคนเห็ดและเป่าเศษขี้เลื่อยออกอย่างนุ่มนวล\n4. บรรจุถุงระบายอากาศพร้อมส่งมอบความสดในวันเดียว','mushroom',50.00,80.00,'กิโลกรัม','หมู่ 13 ต.ลำไทร อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','GAP-TH-13-04-62910','ธนาคารกรุงไทย (KTB)','นายวันชัย รุ่งอรุณ','082-1-49021-3','0869014523','086-901-4523','available','2026-11-05 20:03:43','2026-11-07 15:45:42'),(49,12,3,'น้ำพริกแกงส้มและพริกแกงเขียวหวานปทุมธานี (Green & Sour Curry Paste)','เครื่องแกงส้มและพริกแกงเขียวหวานตำสด รสชาติกลมกล่อม หอมเครื่องเทศพื้นบ้านลาดหลุมแก้ว ปลอดภัย 100%','1. คัดพริกสดขี้นกและสมุนไพรสวนลุ่มน้ำเจ้าพระยา\n2. ล้างน้ำโอโซน บดละเอียดเนื้อเนียน\n3. บรรจุในห้องปลอดเชื้อมาตรฐาน อย.','processed',65.00,80.00,'กระปุก (500 กรัม)','หมู่ 4 ต.คูขวาง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140','ปทุมธานี','ตลาดวิสาหกิจชุมชน','https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1590682680695-43b964a3ae17?w=800&auto=format&fit=crop&q=80','อย. 13-2-02159-2-0003 / มผช. 28/2555','ธนาคารกรุงไทย (KTB)','นายสมควร ชื่นอารมณ์','132-0-45891-2','0819124589','081-912-4589','available','2026-11-05 20:25:18','2026-11-07 15:45:42'),(50,13,4,'ผักสลัดบัตเตอร์เฮดและกรีนโอ๊คอินทรีย์ (Organic Butterhead Salad)','ใบนุ่มกรอบหวาน เก็บเช้ามืด 05:00 น. ล้างโอโซนพร้อมทาน ปลอดสารเคมี 100% สดใหม่จากโรงเรือนบึงคอไห','1. ตัดสดเช้ามืดก่อนแดดส่อง\n2. ล้างระบบน้ำหมุนเวียนโอโซนลดอุณหภูมิใบ\n3. บรรจุถุงควบคุมบรรยากาศคงความกรอบได้นาน','vegetable',55.00,100.00,'ถุง (300 กรัม)','หมู่ 5 ต.บึงคอไห อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','กษ 03-9001-50821-TH','ธนาคารไทยพาณิชย์ (SCB)','นายธนกฤต ศรีบุญเรือง','388-2-41902-8','0897723419','089-772-3419','available','2026-11-05 20:25:18','2026-11-07 15:23:26'),(51,14,5,'เมลอนมัสค์ญี่ปุ่นโรงเรือนควบคุมอุณหภูมิ (Musk Melon)','เมลอนเนื้อเขียว หวานฉ่ำ ลายตาข่ายนูนสวย ปลูก 1 ต้นต่อ 1 ผลในโรงเรือนสมาร์ทฟาร์มสามโคก','1. ตรวจวัดค่าความหวาน Brix 14-16 Brix\n2. ตัดขั้วผลรูปตัว T ช่วงเช้ามืด\n3. บรรจุกล่องโฟมพรีเมียมพร้อมจัดส่ง','fruit',290.00,45.00,'ลูก (1.6-1.8 กก.)','หมู่ 3 ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160 (ติดแม่น้ำเจ้าพระยา)','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800&auto=format&fit=crop&q=80','ORG-TH-13-07-39120','ธนาคารกสิกรไทย (KBANK)','นางสาวกนกพร ลิ้มประเสริฐ','045-8-91230-5','0846398120','084-639-8120','available','2026-11-05 20:25:18','2026-11-07 15:45:42'),(52,15,6,'ข้าวกล้องงอกอินทรีย์กาบาสูตรบำรุงสุขภาพ (Organic GABA Brown Rice)','ข้าวกล้องงอกที่ผ่านการเพาะงอกเพื่อเพิ่มสาร GABA บำรุงระบบประสาทและสมอง ช่วยผ่อนคลาย หลับสบาย','1. คัดเมล็ดข้าวกล้องหอมปทุมสมบูรณ์\n2. นำไปแช่น้ำบ่มเพาะงอกในอุณหภูมิควบคุมเพื่อสร้างสารกาบาสูงสุด\n3. อบแห้งและบรรจุสุญญากาศ','grain',90.00,80.00,'ถุงสุญญากาศ (1 กก.)','หมู่ 2 ต.บึงกาสาม อ.หนองเสือ จ.ปทุมธานี 12170','ปทุมธานี','ตลาดวิสาหกิจชุมชน','https://images.unsplash.com/photo-1536304993881-ff6e9eefa2a6?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','สช 61100098 (GI) / กษ 03-4401-2891','ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร (ธ.ก.ส.)','นายประสิทธิ์ บุญมี','020-2-34981-0','0817028934','081-702-8934','available','2026-11-05 20:25:18','2026-11-07 15:45:42'),(53,16,7,'เมล็ดบัวสดแกะเปลือกพร้อมทานริมเจ้าพระยา (Fresh Lotus Seeds)','เมล็ดบัวหลวงสดใหม่ แกะเปลือกและดึงดีบัวออกเรียบร้อย รสมันหวานกรอบ ทานสดหรือใส่ขนมหวานก็อร่อย','1. เก็บฝักบัวแก่อ่อนกำลังดีช่วงเช้า\n2. แกะเมล็ดและลอกเยื่อบางด้วยมือ\n3. แช่น้ำเย็นรักษาความสด บรรจุถุงสุญญากาศ','processed',75.00,60.00,'ถุง (200 กรัม)','หมู่ 1 ชุมชนวัดไก่เตี้ย ต.กระแชง อ.สามโคก จ.ปทุมธานี 12160','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1509358271058-acd22cc93898?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','มผช. 589/2558 / OTOP-PT-5STAR-012','ธนาคารกรุงไทย (KTB)','นางประทีป อ่อนชื่น','115-1-89302-4','0899832145','089-983-2145','available','2026-11-05 20:25:18','2026-11-07 15:45:42'),(54,17,8,'โจ๊กข้าวอินทรีย์กึ่งสำเร็จรูปพร้อมชงเพื่อสุขภาพ (Instant Organic Rice Porridge)','โจ๊กข้าวหอมปทุมผสมไรซ์เบอร์รี่อินทรีย์ บดละเอียดชงง่ายด้วยน้ำร้อนใน 2 นาที ไม่ใส่ผงชูรส ดีต่อระบบขับถ่าย','1. ใช้ปลายข้าวอินทรีย์จากการสีข้าวกลุ่ม\n2. อบสุกด้วยระบบไอน้ำแรงดันและบดเกล็ด\n3. บรรจุซองฟอยล์กันความชื้น','processed',69.00,85.00,'กล่อง (4 ซอง)','หมู่ 6 ต.ลำลูกกา อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1505253758473-96b3015f210f?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','ORG-TH-13-04-98412','ธนาคารออมสิน (GSB)','นายณัฐพล ใจซื่อ','020-3-48190-2','0873459120','087-345-9120','available','2026-11-05 20:25:18','2026-11-07 15:45:42'),(55,18,9,'มะนาวแปรรูปแช่อิ่มอบน้ำผึ้งชันโรง (Candied Honey Lime)','มะนาวแป้นสดจากสวนลาดหลุมแก้ว แช่อิ่มในน้ำผึ้งชันโรงแท้ รสเปรี้ยวอมหวานชุ่มคอ แก้อาการเจ็บคอ บำรุงเสียง','1. คัดมะนาวแป้นผิวเรียบน้ำดีจากสวน\n2. ล้างยางมะนาวและขูดผิวลดความขม\n3. แช่อิ่มในน้ำผึ้งชันโรงธรรมชาติ 7 วัน บรรจุกระปุกสูญญากาศ','processed',60.00,70.00,'กระปุก (200 กรัม)','หมู่ 3 ต.ระแหง อ.ลาดหลุมแก้ว จ.ปทุมธานี 12140','ปทุมธานี','หน้าสวน','https://images.unsplash.com/photo-1587496679742-bad502958fbf?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','อย. 13-2-03460-6-0002 / มผช. 52/2554','ธนาคารกสิกรไทย (KBANK)','นางสมใจ สุขสวัสดิ์','248-2-39014-7','0834921876','083-492-1876','available','2026-11-05 20:25:18','2026-11-07 15:23:26'),(56,19,10,'เห็ดอบกรอบปรุงรสต้มยำสมุนไพรปลอดสาร (Crispy Tom Yum Mushroom)','เห็ดนางฟ้าฉีกเส้นอบกรอบ คลุกเคล้าเครื่องต้มยำสมุนไพรแท้ กรอบฟิน ไม่อมน้ำมัน เคี้ยวเพลิน มีประโยชน์','1. คัดเห็ดนางฟ้าสดดอกสมบูรณ์ ฉีกเป็นเส้นพอดีคำ\n2. อบด้วยลมร้อนสุญญากาศไล่ความชื้น\n3. คลุกเคล้าผงปรุงรสต้มยำจากสมุนไพรแท้ บรรจุซองฟอยล์ซิปล็อค','processed',49.00,90.00,'ซอง (60 กรัม)','หมู่ 13 ต.ลำไทร อ.ลำลูกกา จ.ปทุมธานี 12150','ปทุมธานี','หน้าแปลง','https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800&auto=format&fit=crop&q=80','/videos/farm-crops.mp4','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80','GAP-TH-13-04-62910','ธนาคารกรุงไทย (KTB)','นายวันชัย รุ่งอรุณ','082-1-49021-3','0869014523','086-901-4523','available','2026-11-05 20:25:18','2026-11-07 15:45:42');
