CREATE TABLE `seller_bank_accounts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seller_id` int NOT NULL,
  `bank_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อธนาคาร',
  `bank_account_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อบัญชีตรงกับชื่อผู้ขาย',
  `bank_account_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'เลขที่บัญชี',
  `promptpay_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'หมายเลขพร้อมเพย์',
  `seller_phone` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'เบอร์โทรหน้าแปลง',
  `is_verified_matching` tinyint(1) DEFAULT '1' COMMENT 'ยืนยันชื่อบัญชีตรงกับผู้ขายแล้ว',
  `is_default` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sba_seller` (`seller_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
