CREATE TABLE `seller_certificates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seller_id` int NOT NULL,
  `cert_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อมาตรฐาน เช่น GAP, GI, Organic Thailand, OTOP',
  `cert_number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'เลขที่ใบรับรอง',
  `issuing_body` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'หน่วยงานที่ออกใบรับรอง',
  `issued_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `cert_image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'รูปถ่ายใบรับรองจริง',
  `status` enum('valid','expired','renewing') COLLATE utf8mb4_unicode_ci DEFAULT 'valid',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_cert_seller` (`seller_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
