INSERT INTO `seller_certificates` VALUES (11,1,'สิ่งบ่งชี้ทางภูมิศาสตร์ (GI) กล้วยหอมทองปทุม & GAP กรมวิชาการเกษตร','สช 64100142 (GI) / กษ 03-9001-3829-TH','กรมทรัพย์สินทางปัญญา และ กรมวิชาการเกษตร',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(12,2,'มาตรฐาน GAP แปลงใหญ่พืชสมุนไพร & รางวัลวิสาหกิจชุมชนดีเด่น','GAP-TH-13-02-49102','สำนักงานเกษตรจังหวัดปทุมธานี กรมส่งเสริมการเกษตร',NULL,NULL,'https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(13,3,'ชนะเลิศวิสาหกิจชุมชนดีเด่นปทุมธานี & OTOP 5 ดาว & อย.','อย. 13-2-02159-2-0003 / มผช. 28/2555','สำนักงานสาธารณสุขจังหวัดปทุมธานี และ กรมการพัฒนาชุมชน',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(14,4,'มาตรฐาน GAP พืชผักปลอดภัย & รางวัลวิสาหกิจชุมชนดีเด่น','กษ 03-9001-50821-TH','สำนักงานเกษตรจังหวัดปทุมธานี',NULL,NULL,'https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(15,5,'มาตรฐาน Organic Thailand & รางวัล Smart Farm BCG Model','ORG-TH-13-07-39120','กรมวิชาการเกษตร และ กระทรวงเกษตรและสหกรณ์',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(16,6,'สิ่งบ่งชี้ทางภูมิศาสตร์ (GI) ข้าวหอมปทุมธานี & GAP ข้าว กรมการข้าว','สช 61100098 (GI) / กษ 03-4401-2891','กรมทรัพย์สินทางปัญญา และ กรมการข้าว',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(17,7,'OTOP 5 ดาว ปทุมธานี & มาตรฐานผลิตภัณฑ์ชุมชน (มผช.)','มผช. 589/2558 / OTOP-PT-5STAR-012','สำนักงานอุตสาหกรรมจังหวัดปทุมธานี',NULL,NULL,'https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(18,8,'มาตรฐานเกษตรอินทรีย์ Organic Thailand (มกษ. 9000)','ORG-TH-13-04-98412','กรมการข้าว และ กรมวิชาการเกษตร',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(19,9,'มาตรฐานผลิตภัณฑ์ชุมชน (มผช.) & OTOP 4 ดาว & อย.','อย. 13-2-03460-6-0002 / มผช. 52/2554','สำนักงานสาธารณสุขจังหวัดปทุมธานี',NULL,NULL,'https://images.unsplash.com/photo-1554415707-9e49fe832873?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18'),(20,10,'มาตรฐาน GAP เห็ดปลอดภัย & OTOP ปทุมธานี','GAP-TH-13-04-62910','สำนักงานเกษตรจังหวัดปทุมธานี กรมวิชาการเกษตร',NULL,NULL,'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','valid','2026-11-05 20:25:18','2026-11-05 20:25:18');
