CREATE TABLE `seller_ledger` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seller_id` int NOT NULL,
  `entry_type` enum('revenue','expense') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'revenue=รายรับ, expense=รายจ่าย',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'หมวดหมู่ เช่น ขายผลผลิต, ปุ๋ยอินทรีย์, บรรจุภัณฑ์',
  `amount` decimal(12,2) NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รหัสอ้างอิง เช่น เลขที่ออเดอร์',
  `transaction_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ledger_seller` (`seller_id`),
  KEY `idx_ledger_date` (`transaction_date`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
