INSERT INTO `sellers` VALUES (1,10,'1-13-05-01/1-0028','วิสาหกิจชุมชนกลุ่มกล้วยหอมทองปทุมรัตน์ (แปลงใหญ่กล้วยหอมทองตำบลนพรัตน์)','นายนุกุล นามปราศัย','081-817-9418','homthong.noprat@plukrak.local','กลุ่มเกษตรกรแปลงใหญ่กล้วยหอมทองที่ใหญ่และมีชื่อเสียงที่สุดในจังหวัดปทุมธานี ได้รับการขึ้นทะเบียนสิ่งบ่งชี้ทางภูมิศาสตร์ (GI) \'กล้วยหอมทองปทุม\' กล้วยมีผลใหญ่ยาว เปลือกบาง ผิวนวล เนื้อแน่น และรสชาติหวานหอม ปลูกด้วยวิถี BCG Model',NULL,NULL,'/videos/farm-crops.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26'),(2,11,'1-13-02-03/1-0015','วิสาหกิจชุมชนแปลงใหญ่เตยหอมคลองสาม','นางสมปอง คำสวัสดิ์','086-554-9123','toeyhom.klongsam@plukrak.local','ต้นแบบวิสาหกิจชุมชนดีเด่นระดับจังหวัดปทุมธานี (รางวัลรองชนะเลิศอันดับ 1) รวมกลุ่มเกษตรกรปลูกเตยหอมอินทรีย์แปลงใหญ่ ปลูกในร่องสวนที่มีสภาพดินเหนียวอุดมสมบูรณ์ ส่งผลให้ใบเตยมีความหอมเข้มข้นเป็นพิเศษ ปลอดสารเคมี 100%',NULL,NULL,'/videos/farm-field.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:45:42'),(3,12,'1-13-06-02/1-0009','วิสาหกิจชุมชนน้ำพริกแกงพ่อกำนัน','นายสมควร ชื่นอารมณ์ (กำนันสมควร)','081-912-4589','namphrik.kamnan@plukrak.local','ชนะเลิศอันดับ 1 วิสาหกิจชุมชนดีเด่นระดับจังหวัดปทุมธานี นำภูมิปัญญาการทำเครื่องแกงโบราณรสเด็ดประจำถิ่นลาดหลุมแก้ว ใช้วัตถุดิบสมุนไพรสดปลอดสารจากเกษตรกรในพื้นที่ โขลกและบดสดใหม่ ไม่ใส่ผงชูรสและสารกันเสีย',NULL,NULL,'/videos/farm-greenhouse.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26'),(4,13,'1-13-04-06/1-0033','วิสาหกิจชุมชนเกษตรใบเขียว (Green Leaf Organic Farm)','นายธนกฤต ศรีบุญเรือง','089-772-3419','greenleaf.lamlukka@plukrak.local','รองชนะเลิศอันดับ 2 วิสาหกิจชุมชนดีเด่นจังหวัดปทุมธานี ฟาร์มผักสลัดและเคลออร์แกนิกระบบโรงเรือนตาข่ายกันแมลง ใช้ปุ๋ยหมักมูลไส้เดือนดินและน้ำหมักชีวภาพ ได้รับความไว้วางใจจากร้านอาหารสุขภาพทั่วกรุงเทพฯ และปริมณฑล',NULL,NULL,'/videos/farm-crops.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26'),(5,14,'1-13-07-03/1-0041','วิสาหกิจชุมชน Gfarm at Samkhok (จีฟาร์ม แอท สามโคก)','นางสาวกนกพร ลิ้มประเสริฐ','084-639-8120','gfarm.samkhok@plukrak.local','ฟาร์มเกษตรแม่นยำสูง (Smart Farming) ริมแม่น้ำเจ้าพระยา ปลูกมะเขือเทศเชอร์รี่สีทองและเมลอนญี่ปุ่นในโรงเรือนควบคุมสภาพแวดล้อมอัตโนมัติ ผลผลิตมีรสหวานกรอบเข้มข้น ปราศจากสารเคมีสังเคราะห์ทุกขั้นตอน',NULL,NULL,'/videos/farm-field.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26'),(6,15,'1-13-05-04/1-0012','วิสาหกิจชุมชนกลุ่มผลิตเมล็ดพันธุ์ข้าวและแปรรูปข้าวบ้านบึงสมบูรณ์','นายประสิทธิ์ บุญมี','081-702-8934','buengsomboon.rice@plukrak.local','กลุ่มเกษตรกรผู้ผลิตและแปรรูปข้าวหอมปทุมธานี 1 ที่ได้รับการขึ้นทะเบียนสินค้าสิ่งบ่งชี้ทางภูมิศาสตร์ (GI) ปลูกด้วยระบบ GAP ข้าว ปลอดสารพิษ มีโรงสีข้าวพลังงานแสงอาทิตย์ของชุมชนที่สีสดใหม่ตามคำสั่งซื้อ ข้าวสารจึงคงความหอมนุ่มอร่อย',NULL,NULL,'/videos/farm-nature.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:45:42'),(7,16,'1-13-07-01/1-0018','วิสาหกิจชุมชนกลุ่มแสงตะวัน (ใยกล้วยบัวหลวง & ผลิตภัณฑ์บัวสามโคก)','นางประทีป อ่อนชื่น','089-983-2145','saengtawan.samkhok@plukrak.local','ชุมชนมอญดั้งเดิมแห่งสามโคก สืบสานภูมิปัญญาเมืองบัวหลวง ปลูกบัวหลวงอินทรีย์ริมน้ำ นำทุกส่วนของบัวมาสร้างมูลค่าเพิ่ม ทั้งเกสรบัว เมล็ดบัว และริเริ่มนวัตกรรม \'ใยกล้วยบัวหลวง\' ได้รับรางวัลผลิตภัณฑ์สร้างสรรค์ OTOP ปทุมธานี',NULL,NULL,'/videos/farm-nature.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26'),(8,17,'1-13-04-01/1-0022','วิสาหกิจชุมชนเพราะรักกสิกรรม (นาแปลงใหญ่ข้าวอินทรีย์ลำลูกกา)','นายณัฐพล ใจซื่อ','087-345-9120','praorak.rice@plukrak.local','กลุ่มเกษตรกรรุ่นใหม่ผู้มุ่งมั่นทำนาข้าวอินทรีย์มาตรฐาน Organic Thailand ไม่ใช้สารเคมีและปุ๋ยสังเคราะห์ ปลูกข้าวไรซ์เบอร์รี่และข้าวหอมปทุมอินทรีย์ แปรรูปเป็นโจ๊กและข้าวกล้องเพื่อสุขภาพ',NULL,NULL,'/videos/farm-crops.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:45:42'),(9,18,'1-13-06-01/1-0005','วิสาหกิจชุมชนกลุ่มแม่บ้านเกษตรกรตับผักชี','นางสมใจ สุขสวัสดิ์','083-492-1876','maeban.tubphakchee@plukrak.local','กลุ่มแม่บ้านเกษตรกรแปรรูปผลผลิตการเกษตรพื้นถิ่นลาดหลุมแก้ว นำกล้วยน้ำว้าและมะนาวจากสวนสมาชิกมาแปรรูปเป็นของว่างเพื่อสุขภาพ รสชาติกลมกล่อมตามแบบฉบับขนมไทยโบราณ สร้างงานสร้างรายได้ให้แก่สตรีในชุมชน',NULL,NULL,'/videos/farm-field.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:45:42'),(10,19,'1-13-04-03/1-0019','วิสาหกิจชุมชนเห็ดเศรษฐกิจและแปรรูปลำไทรพัฒนา','นายวันชัย รุ่งอรุณ','086-901-4523','mushroom.lamsai@plukrak.local','ศูนย์เรียนรู้การเพาะเห็ดเศรษฐกิจปลอดภัยชุมชนลำไทร ใช้เทคโนโลยีควบคุมอุณหภูมิและความชื้นด้วยเซนเซอร์ ไม่ใช้สารฟอร์มาลินและสารเคมีทุกชนิด เห็ดมีดอกหนานุ่ม หวานกรอบ พร้อมแปรรูปเป็นเห็ดสวรรค์และเห็ดอบกรอบ',NULL,NULL,'/videos/farm-greenhouse.mp4',1,'2026-11-05 20:03:43','2026-11-07 15:23:26');
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `full_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `google_sub` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role_id` bigint unsigned NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `google_sub` (`google_sub`),
  UNIQUE KEY `uq_users_google_sub` (`google_sub`),
  KEY `role_id` (`role_id`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
